7	+package hotel.documents;
8	+
9	+import hotel.reservations.Reservation;
10	+import hotel.rooms.Room;
11	+import hotel.rooms.RoomType;
12	+import java.math.BigDecimal;
13	+import java.math.RoundingMode;
14	+import java.time.LocalDate;
15	+
16	+/** The invoice for a company identified by CNPJ. */
17	+public record CompanyInvoice(
18	+        String title,
19	+        long reservationId,
20	+        String guestName,
21	+        String guestCpf,
22	+        String companyCnpj,
23	+        String companyName,
24	+        String guestPassport,
25	+        String guestCountry,
26	+        int roomNumber,
27	+        RoomType roomType,
28	+        LocalDate checkIn,
29	+        LocalDate checkOut,
30	+        int nights,
31	+        BigDecimal subtotal,
32	+        BigDecimal discount,
33	+        BigDecimal total) implements ReservationDocument {
34	+
35	+    private static final BigDecimal ISS_RATE = new BigDecimal("0.05"); // 5%
36	+
37	+    public CompanyInvoice(Reservation reservation, Room room) {
38	+        this(
39	+                "Fatura de hospedagem",
40	+                reservation.id(),
41	+                reservation.guest().name(),
42	+                null,
43	+                reservation.guest().companyCnpj(),
44	+                reservation.guest().companyName(),
45	+                null,
46	+                null,
47	+                room.number(),
48	+                room.type(),
49	+                reservation.checkIn(),
50	+                reservation.checkOut(),
51	+                reservation.price().nights(),
52	+                reservation.price().subtotal(),
53	+                reservation.price().discount(),
54	+                reservation.price().total());
55	+    }
56	+
57	+    @Override
58	+    public String text() {
59	+        StringBuilder text = new StringBuilder();
60	+        text.append(title).append(" nº ").append(reservationId).append('\n');
61	+        text.append("Empresa: ").append(companyName).append(" (CNPJ ").append(companyCnpj).append(")\n");
62	+        text.append("Hóspede: ").append(guestName).append('\n');
63	+        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
64	+        text.append("Entrada: ").append(TextFormat.date(checkIn))
65	+                .append(" | Saída: ").append(TextFormat.date(checkOut))
66	+                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
67	+        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
68	+        if (discount.signum() > 0) {
69	+            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
70	+        }
71	+        text.append("Total: ").append(TextFormat.money(total)).append('\n');
72	+
73	+        // ISS retido (5% do total)
74	+        BigDecimal iss = total.multiply(ISS_RATE).setScale(2, RoundingMode.HALF_EVEN);
75	+        text.append("ISS retido (5%): ").append(TextFormat.money(iss)).append('\n');
76	+
77	+        return text.toString();
78	+    }
79	+}
