139	+                .append(" (passport ").append(guestPassport)
140	+                .append(", ").append(guestCountry).append(")\n");
141	+        text.append("Room: ").append(roomNumber).append(" (").append(roomType).append(")\n");
142	+        text.append("Check-in: ").append(checkIn)
143	+                .append(" | Check-out: ").append(checkOut)
144	+                .append(" | ").append(nights).append(nights == 1 ? " night" : " nights").append('\n');
145	+        text.append("Nights: ").append(formatMoney(subtotal)).append('\n');
146	+        if (discount.signum() > 0) {
147	+            text.append("Discount: ").append(formatMoney(discount)).append('\n');
