233	+package hotel.documents;
234	+
235	+import hotel.reservations.Reservation;
236	+import hotel.rooms.Room;
237	+import hotel.rooms.RoomType;
238	+import java.math.BigDecimal;
239	+import java.time.LocalDate;
240	+
241	+/** A document about a reservation: receipt, invoice, or booking receipt. */
242	+public sealed interface ReservationDocument permits PersonReceipt, CompanyInvoice, ForeignerReceipt {
243	+
244	+    String title();
245	+    long reservationId();
246	+    String guestName();
247	+    String guestCpf();
248	+    String companyCnpj();
249	+    String companyName();
250	+    String guestPassport();
251	+    String guestCountry();
252	+    int roomNumber();
253	+    RoomType roomType();
254	+    LocalDate checkIn();
255	+    LocalDate checkOut();
256	+    int nights();
257	+    BigDecimal subtotal();
258	+    BigDecimal discount();
259	+    BigDecimal total();
260	+
261	+    /** The formatted text of the document. */
262	+    String text();
263	+
264	+    /** Creates the appropriate document type for the given reservation. */
265	+    static ReservationDocument of(Reservation reservation, Room room) {
266	+        if (reservation.guest().isCompany()) {
267	+            return new CompanyInvoice(reservation, room);
268	+        } else if (reservation.guest().isForeigner()) {
269	+            return new ForeignerReceipt(reservation, room);
270	+        } else {
271	+            return new PersonReceipt(reservation, room);
272	+        }
273	+    }
274	+}
