   147	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
   148	public record ReservationReceipt(
   149	        String title,
   150	        long reservationId,
   151	        String guestName,
   152	        String guestCpf,
   153	        String companyCnpj,
   154	        String companyName,
   155	        String guestPassport,
   156	        String guestCountry,
   157	        int roomNumber,
   158	        RoomType roomType,
   159	        LocalDate checkIn,
   160	        LocalDate checkOut,
   161	        int nights,
   162	        BigDecimal subtotal,
   163	        BigDecimal discount,
   164	        BigDecimal total,
   165	        String text) {
   166	
   167	    public ReservationReceipt(Reservation reservation, Room room) {
   168	        this(ReservationDocument.of(reservation, room));
   169	    }
   170	
   171	    private ReservationReceipt(ReservationDocument document) {
   172	        this(
   173	                document.title(),
   174	                document.reservationId(),
   175	                document.guestName(),
   176	                document.guestCpf(),
   177	                document.companyCnpj(),
   178	                document.companyName(),
   179	                document.guestPassport(),
   180	                document.guestCountry(),
   181	                document.roomNumber(),
   182	                document.roomType(),
   183	                document.checkIn(),
   184	                document.checkOut(),
   185	                document.nights(),
   186	                document.subtotal(),
   187	                document.discount(),
   188	                document.total(),
   189	                document.text());
   190	    }
   191	
   192	    /** @deprecated Use the text field instead. */
   193	    @Deprecated
   194	    public String text() {
   195	        return text;
   196	    }
   197	}
