   200	import java.math.BigDecimal;
   201	import java.time.LocalDate;
   202	import java.time.format.DateTimeFormatter;
   203	import java.util.Locale;
   204	
   205	/** How money and dates are written in the texts the guest reads (Brazilian Portuguese). */
   206	public final class TextFormat {
   207	
   208	    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
   209	    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
   210	
   211	    private TextFormat() {
   212	    }
   213	
   214	    public static String money(BigDecimal amount) {
   215	        return "R$ " + String.format(BRAZIL, "%,.2f", amount);
   216	    }
   217	
   218	    public static String date(LocalDate date) {
   219	        return BRAZILIAN_DATE.format(date);
   220	    }
   221	}
   222	package hotel.reservations;
   223	
   224	import hotel.rooms.Room;
   225	import java.math.BigDecimal;
   226	import java.math.RoundingMode;
   227	import java.time.LocalDate;
   228	import java.time.Month;
   229	
   230	/**
   231	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   232	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
   233	 * (half-even) at every step.
   234	 */
   235	public final class PriceCalculator {
   236	
   237	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   238	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
   239	
   240	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
   241	        int nights = 0;
   242	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   243	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
   244	            subtotal = subtotal.add(nightPrice(room, night));
   245	            nights++;
   246	        }
   247	        BigDecimal discount = switch (ratePlan) {
   248	            case STANDARD -> cents(BigDecimal.ZERO);
   249	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
   250	        };
   251	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
   252	    }
   253	
   254	    BigDecimal nightPrice(Room room, LocalDate night) {
   255	        BigDecimal nightlyRate = room.nightlyRate();
   256	        if (isHighSeason(night)) {
   257	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   258	        }
   259	        return cents(nightlyRate);
   260	    }
   261	
   262	    /** High season: from December 15 to the end of February, and the whole of July. */
   263	    static boolean isHighSeason(LocalDate date) {
   264	        Month month = date.getMonth();
   265	        return month == Month.JANUARY
   266	                || month == Month.FEBRUARY
   267	                || month == Month.JULY
   268	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   269	    }
   270	
   271	    static BigDecimal cents(BigDecimal value) {
   272	        return value.setScale(2, RoundingMode.HALF_EVEN);
   273	    }
   274	}
