133	    private static Guest validateAndCreateGuest(CreateReservationRequest body) {
134	        boolean hasCpf = !isBlank(body.guestCpf());
135	        boolean hasCompany = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
136	        boolean hasPassport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());
137	
138	        // Count how many identification types are provided
139	        int identificationCount = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);
140	
141	        if (identificationCount != 1) {
142	            throw new HotelException(ErrorCode.INVALID_REQUEST,
143	                    "must provide exactly one identification: guestCpf, or (companyCnpj and companyName), "
144	                    + "or (guestPassport and guestCountry)");
145	        }
146	
147	        if (hasCpf) {
148	            return Guest.withCpf(body.guestName(), body.guestEmail(), body.guestCpf());
149	        } else if (hasCompany) {
150	            return Guest.withCompany(body.guestName(), body.guestEmail(), body.companyCnpj(), body.companyName());
151	        } else {
152	            return Guest.withPassport(body.guestName(), body.guestEmail(), body.guestPassport(), body.guestCountry());
153	        }
154	    }
