167	        try {
168	            return LocalDate.parse(date);
169	        } catch (DateTimeParseException badDate) {
170	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
171	        }
172	    }
173	
174	    private static YearMonth readMonth(Context ctx) {
175	        String month = requiredQueryParam(ctx, "month");
176	        try {
177	            return YearMonth.parse(month);
178	        } catch (DateTimeParseException badMonth) {
179	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
180	        }
181	    }
